out=[[0]*15 for _ in range(15)]
# colored rows: fill gaps with row color
for r,segs in [(2,[(0,2),(4,5)]),(3,[(6,7),(9,14)]),(6,[(0,2),(4,6)]),(8,[(6,7),(9,14)]),(12,[(0,2),(4,7),(9,14)])]:
    c=({2:2,3:3,6:3,8:9,12:4})[r]
    for a,b in segs:
        for j in range(a,b+1): out[r][j]=c
# marker columns/rows to edges, colored cells take precedence (demo: row9 col3 stayed 2)
for i in range(15):
    if out[i][3]==0: out[i][3]=6
for j in range(15):
    if out[14][j]==0: out[14][j]=8
for r in out: print(''.join(map(str,r)))

grid=[[0]*15 for _ in range(15)]
rows={2:(2,[(0,2),(4,5)]),3:(5,[(6,7),(9,14)]),6:(3,[(0,2),(4,6)]),8:(9,[(6,7),(9,14)]),12:(4,[(0,2),(4,7),(9,14)])}
for r,(c,segs) in rows.items():
    for i,(a,b) in enumerate(segs):
        hi = segs[i+1][0]-1 if i+1<len(segs) else b
        for j in range(a,hi+1): grid[r][j]=c
# column carry for marker columns
cols={3:6,6:8,8:8}
for c,m in cols.items():
    cur=m
    for i in range(14,-1,-1):
        if grid[i][c]!=0: cur=grid[i][c]
        else: grid[i][c]=cur
for r in grid: print(''.join(map(str,r)))
